Gemini said

To export your current browser-based chat session into a JSON file, open the Developer Tools Console (F12 or Ctrl+Shift+J / Cmd+Option+J) on your chat page, paste the script below, and press Enter.   
GitHub

This script automatically scrapes the user prompts and model responses, packages them into a clean JSON structure, and triggers a file download in your browser.

JavaScript
(() => {
  const turns = [];

  // Target standard chat web elements (adaptable across platforms like Gemini web)
  const messageElements = document.querySelectorAll('user-query, model-response, .message-container, [data-test-id*="message"], article');

  if (messageElements.length > 0) {
    messageElements.forEach(el => {
      const tag = el.tagName ? el.tagName.toLowerCase() : '';
      const className = el.className ? el.className.toString() : '';

      // Determine sender role based on element tags or classes
      const isUser = tag.includes('user') || className.includes('user') || el.querySelector('.user-query');
      const role = isUser ? 'user' : 'model';

      const text = el.innerText ? el.innerText.trim() : '';
      if (text) {
        turns.push({
          role: role,
          content: text
        });
      }
    });
  }

  if (turns.length === 0) {
    console.warn("Could not find structured chat containers. Trying generic text node extraction...");
    // Fallback: Grab text blocks if layout is custom
    document.querySelectorAll('p, pre, code').forEach(node => {
      const text = node.innerText.trim();
      if (text.length > 0) {
        turns.push({ role: 'text_block', content: text });
      }
    });
  }

  if (turns.length === 0) {
    alert("No messages found to export. Ensure the chat is fully loaded.");
    return;
  }

  // Construct the export payload
  const chatData = {
    exportedAt: new Date().toISOString(),
    sourceUrl: window.location.href,
    messageCount: turns.length,
    messages: turns
  };

  // Convert to JSON and trigger file download
  const jsonStr = JSON.stringify(chatData, null, 2);
  const blob = new Blob([jsonStr], { type: 'application/json' });
  const url = URL.createObjectURL(blob);

  const downloadLink = document.createElement('a');
  downloadLink.href = url;
  downloadLink.download = `chat-export-${new Date().toISOString().slice(0, 10)}.json`;
  document.body.appendChild(downloadLink);
  downloadLink.click();

  document.body.removeChild(downloadLink);
  URL.revokeObjectURL(url);

  console.log(`%c Success! Exported ${turns.length} chat items to JSON.`, "color: #10b981; font-weight: bold;");
})();
